from io import StringIO

def exporter_catalogue(texte_json):
    fiches = valider_catalogue(decoder_json(texte_json))
    flux = StringIO(newline='')
    auteur = csv.DictWriter(flux, fieldnames=['id', 'nom', 'places'], delimiter=';', lineterminator='\r\n', quoting=csv.QUOTE_ALL)
    auteur.writeheader()
    auteur.writerows(fiches)
    return flux.getvalue()

